/**
 * @noflo/assembly-utils - Assembly adapter components for NoFlo
 * Collect inner component outputs back into the originating assembly message.
 * SPDX-License-Identifier: MIT
 */
/* @ts-self-types="./CollectFields.d.ts" */
import Component from "@noflo/assembly";

/**
 * Collects the inner component's outputs back into the originating
 * assembly message.
 *
 * The adapter graphs generated by `asAssembly` wire the inner
 * component's outports to the addressable `data` port — one connection
 * per mapped field, in field order — and the originating message to
 * `msg`. The collector fires when every mapped field delivered; a
 * bracketed inner stream collects as an array under the field key, a
 * single packet as the value itself. When the inner signalled failure
 * through its `error` port instead (work document #36: components
 * signal failure through the error port rather than their data
 * outports), the collector fires with the errors accumulated into
 * `msg.errors` and whatever fields did deliver.
 *
 * The error port is the message's terminal event for its scope: firing
 * on it completes the message even while other fields' streams are
 * still open, because a failed inner will not deliver them. Inner data
 * arriving after the error for the same scope has no collector waiting
 * and surfaces in the shutdown diagnostics — inner components signal
 * failure instead of continuing to deliver. Pairing is per scope:
 * concurrent in-flight messages must carry scopes (the message's scope
 * propagates through the fanout, extractors, and inner, so every leg of
 * one message shares it), and the scope-aware has-checks resolve each
 * message's legs independently — unscoped concurrent in-flight messages
 * pair positionally and cross (work document #35 update #13, question
 * (c); the liveness that makes the scoped wait safe is work document
 * #45).
 */
export class CollectFields extends Component {
  constructor() {
    super({
      description: "Collect inner component outputs into an assembly message",
      icon: "sign-in",
      inPorts: {
        msg: {
          datatype: "object",
          description: "The originating assembly message",
          required: true,
        },
        data: {
          datatype: "all",
          description: "Inner outport values, one connection per field",
          addressable: true,
          required: false,
        },
        fields: {
          datatype: "string",
          description: "JSON array of field names in data-connection order",
          required: false,
          control: true,
        },
        error: {
          datatype: "object",
          description: "Inner component errors",
          required: false,
        },
      },
      outPorts: {
        out: {
          datatype: "object",
          description: "The message with the collected fields merged in",
        },
      },
    });
  }

  processMessage(input, output) {
    if (!input.hasData("msg", "fields")) {
      return;
    }

    const indexes = /** @type {number[]} */ (input.attached("data"));
    const complete = indexes.filter((idx) => input.hasStream(["data", idx]));
    const errorStream = input.hasStream("error");

    // Fire only when the message can be consumed together with its inner
    // outputs (or the inner signalled failure). Has-check everything before
    // any get: consuming the message in an activation that then waits for
    // the inner leg would lose it — new arrivals fire fresh contexts, and
    // an IP consumed by a waiting activation never comes back (the has/get
    // order discipline, work documents #21 and #36). Leaving the message
    // buffered keeps it readable by the activation that fires once every
    // field has delivered.
    if (complete.length < indexes.length && !errorStream) {
      return;
    }

    const msg = input.getData("msg");
    const fieldNames = JSON.parse(input.getData("fields"));

    // Fire when every mapped field delivered, or when the inner
    // signalled an error instead of delivering
    const result = { ...msg };
    /** @type {unknown[]} */
    const errors = Array.isArray(msg.errors) ? [...msg.errors] : [];
    if (errorStream) {
      for (const ip of input.getStream("error")) {
        if (ip.type !== "data") {
          continue;
        }
        errors.push(ip.data);
      }
    }
    for (const idx of complete) {
      const field = fieldNames[idx];
      if (field === undefined) {
        continue;
      }
      const stream = input.getStream(["data", idx]);
      const values = stream
        .filter((ip) => ip.type === "data")
        .map((ip) => ip.data);
      // A bracketed inner stream collects as an array; a single packet
      // as the value itself
      result[field] = values.length === 1 ? values[0] : values;
    }
    result.errors = errors;
    output.sendDone({ out: result });
  }
}

/**
 * CollectFields component factory: the loader instantiates the component
 * for a graph node.
 *
 * @returns {CollectFields} The component instance.
 */
export function getComponent() {
  return new CollectFields();
}
